export function createLedger({ expectedAmounts = {} } = {}) {
  const handledIds = new Set();
  const entries = new Map();
  const knownTypes = new Set([
    "charge.success",
    "charge.failed",
    "charge.abandoned",
    "refund.processed",
  ]);
  const terminalChargeStatuses = new Set([
    "success",
    "partially_refunded",
    "refunded",
    "amount_mismatch",
  ]);

  function createEntry(reference) {
    const hasExpectedAmount =
      expectedAmounts != null &&
      Object.prototype.hasOwnProperty.call(expectedAmounts, reference);
    const expectedAmount = hasExpectedAmount
      ? expectedAmounts[reference]
      : null;

    return {
      reference,
      status: "pending",
      amountKobo: expectedAmount,
      refundedKobo: 0,
      hasExpectedAmount,
      expectedAmount,
      deferredRefunds: [],
    };
  }

  function applyRefund(entry, amountKobo) {
    const newTotal = entry.refundedKobo + amountKobo;

    if (newTotal > entry.amountKobo) {
      return false;
    }

    entry.refundedKobo = newTotal;
    entry.status =
      newTotal === entry.amountKobo ? "refunded" : "partially_refunded";
    return true;
  }

  function handle(event) {
    if (!event || !knownTypes.has(event.type)) {
      return {
        applied: false,
        reason: "unknown-type",
        status: null,
      };
    }

    const existingEntry = entries.get(event.reference);

    if (handledIds.has(event.id)) {
      return {
        applied: false,
        reason: "duplicate",
        status: existingEntry ? existingEntry.status : null,
      };
    }

    if (
      (event.type === "charge.success" ||
        event.type === "refund.processed") &&
      (!Number.isInteger(event.amountKobo) || event.amountKobo <= 0)
    ) {
      return {
        applied: false,
        reason: "invalid-amount",
        status: existingEntry ? existingEntry.status : null,
      };
    }

    handledIds.add(event.id);

    let entry = existingEntry;
    if (!entry) {
      entry = createEntry(event.reference);
      entries.set(event.reference, entry);
    }

    if (event.type !== "refund.processed") {
      if (terminalChargeStatuses.has(entry.status)) {
        return {
          applied: false,
          reason: "terminal",
          status: entry.status,
        };
      }

      if (event.type === "charge.failed") {
        if (entry.status === "failed") {
          return {
            applied: false,
            reason: "stale",
            status: entry.status,
          };
        }

        entry.status = "failed";
        return {
          applied: true,
          reason: null,
          status: entry.status,
        };
      }

      if (event.type === "charge.abandoned") {
        if (entry.status === "abandoned" || entry.status === "failed") {
          return {
            applied: false,
            reason: "stale",
            status: entry.status,
          };
        }

        entry.status = "abandoned";
        return {
          applied: true,
          reason: null,
          status: entry.status,
        };
      }

      if (
        entry.hasExpectedAmount &&
        event.amountKobo !== entry.expectedAmount
      ) {
        entry.status = "amount_mismatch";
        entry.deferredRefunds.length = 0;

        return {
          applied: true,
          reason: "amount-mismatch",
          status: entry.status,
        };
      }

      entry.amountKobo = entry.hasExpectedAmount
        ? entry.expectedAmount
        : event.amountKobo;
      entry.status = "success";

      for (const refundAmount of entry.deferredRefunds) {
        applyRefund(entry, refundAmount);
      }
      entry.deferredRefunds.length = 0;

      return {
        applied: true,
        reason: null,
        status: entry.status,
      };
    }

    if (
      entry.status === "success" ||
      entry.status === "partially_refunded"
    ) {
      if (!applyRefund(entry, event.amountKobo)) {
        return {
          applied: false,
          reason: "over-refund",
          status: entry.status,
        };
      }

      return {
        applied: true,
        reason: null,
        status: entry.status,
      };
    }

    if (entry.status === "refunded") {
      return {
        applied: false,
        reason: "over-refund",
        status: entry.status,
      };
    }

    if (entry.status === "amount_mismatch") {
      return {
        applied: false,
        reason: "terminal",
        status: entry.status,
      };
    }

    entry.deferredRefunds.push(event.amountKobo);
    return {
      applied: false,
      reason: "deferred",
      status: entry.status,
    };
  }

  function get(reference) {
    const entry = entries.get(reference);

    if (!entry) {
      return undefined;
    }

    return {
      reference: entry.reference,
      status: entry.status,
      amountKobo: entry.amountKobo,
      refundedKobo: entry.refundedKobo,
    };
  }

  return { handle, get };
}
